                    if (nl_attr_type(act) == OVS_ACTION_ATTR_PSAMPLE) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    case OVS_ACTION_ATTR_UNSPEC:
    case __OVS_ACTION_ATTR_MAX:
        OVS_NOT_REACHED();
